        st.appendChild(svgEl("path", { d: "M0 0v-44", stroke: "#7f9c3e", "stroke-width": "2.6", "stroke-linecap": "round" }));
        st.appendChild(svgEl("path", { d: "M0 -24c-11-2-16-9-16-17 10 0 16 7 16 17Z", fill: "#8aa347" }));
