      var r = svgEl("path", {
        d: "M" + x.toFixed(0) + " 812c-3 12 2 18-1 30M" + x.toFixed(0) + " 816c5 6 7 13 6 22M" + x.toFixed(0) + " 816c-6 7-8 14-7 24",
        fill: "none", stroke: "#8a5a33", "stroke-width": "1.1", "stroke-linecap": "round", opacity: ".3"
      });
