      WATER[ctx.water].n + " · " + s.n + " soil. Ranked for " +
      ({ income: "maximum income", safe: "lowest risk", short: "short duration", soil: "soil health" }[ctx.goal]) + ".";

    var k = $("#kpis"); k.textContent = "";
