      var mS = new Date(A.sow).getUTCMonth(), overl = function () { var t; for (t = A.sow; t <= e; t += 7 * DAY) { var d = new Date(t), m = d.getUTCMonth() + 1, dd = d.getUTCDate(); if ((m === 10 && dd >= 15) || m === 11 || (m === 12 && dd <= 15)) return true } return false };
      if (coastal && overl()) {
        out.push({
          id: "cyclone", en: "Cyclone / heavy north-east monsoon spell", te: "తుఫాను / ఈశాన్య రుతుపవనాల వర్షం", tf: "తుఫాను హెచ్చరికలు గమనించండి; కోతకు వచ్చిన పంటను ముందే కోయండి; మురుగు కాలువలు సిద్ధం చేయండి.",
          p: .3, sev: 2, stage: -1, score: 1.6, k: 0, N: 0, static: true,
          why: "Mid-October to mid-December is the cyclone and north-east monsoon window on the Andhra coast; your crop cycle overlaps it. Roughly one year in three brings a damaging system to some part of the coast.",
          fix: ["Follow IMD cyclone bulletins and the district alert; do not wait for a landfall forecast to act.", "Cut drains and clear outlets before the season starts; harvest mature crop ahead of a warning and keep produce dry and raised.", "Prop banana and tall crops before winds; drain tanks and keep seed and inputs off the ground."]
        });
      }
      var seasonOK = crop.se[seasonOf(A.sow)] || 0;
