      k.appendChild(kpi("Rain in the cycle", r0(rain) + " mm", "typical"));
      k.appendChild(kpi("Irrigation need", r0(irr) + " mm", "≈ " + (lakh < 1 ? lakh.toFixed(2) : lakh.toFixed(1)) + " lakh L"));
      k.appendChild(kpi(A.S_.per ? "Review at" : "Harvest", fD(A.sow + H * DAY), new Date(A.sow + H * DAY).getUTCFullYear()));
      k.appendChild(kpi("Data", D.hist ? "Live" : "Estimated", D.hist ? "25-yr history" : "built-in climate"));
